/**********************************************************************************
  売上実績処理 PK違反 確認用SQL（初回対応）

    作成日   : 2026/08/13
    対象DB   : SIMTOKIDB
    対象事象 : PK_売上実績テーブル 違反 / 重複キー (1196362, 3, 202607)

    ※ すべて参照系（SELECT）です。データの更新・削除は行いません。
    ※ ①から順に実行し、結果をご提供ください。
**********************************************************************************/
USE [SIMTOKIDB]
GO
SET NOCOUNT ON
GO

DECLARE @KNO   INT         = 1196362      -- 重複した検収管理NO
DECLARE @GYO   TINYINT     = 3            -- 重複した検収管理行NO
DECLARE @YM    VARCHAR(6)  = '202607'     -- 重複した実績年月
DECLARE @TORCD VARCHAR(7)  = ''           -- ★対象の契約先CD（分かれば設定。空なら全件）

PRINT '========== ① 重複キーの実体（売上実績テーブル） =========='
--  入力区分 = ''  → 売上実績作成（検収由来）
--  入力区分 = '2' → 売上実績型費（型費由来）
SELECT  検収管理NO, 検収管理行NO, 実績年月, 入力区分,
        契約先, 納入先, 受入, 品番, 納入番号, 検収年月日,
        納入数, 単価, 金額, 締日, 明細件数,
        実績処理日, 作成日, 作成端末, 作成者
  FROM  売上実績テーブル
 WHERE  検収管理NO = @KNO
   AND  検収管理行NO = @GYO
 ORDER BY 実績年月

検収管理NO	検収管理行NO	実績年月	入力区分	契約先	納入先	受入	品番	納入番号	検収年月日	納入数	単価	金額	締日	明細件数	実績処理日	作成日	作成端末	作成者
1196362	3	202607		NULL	1048	01	6143190K00	R1970	20260701	10	234.81	0	NULL	1	20260805	2026-08-05 10:16:23.150	営業技術2023	


PRINT '========== ①-2 同一検収管理NOの全行（行NO・年月を問わず） =========='
SELECT  検収管理NO, 検収管理行NO, 実績年月, 入力区分, 契約先, 品番, 金額, 作成日, 作成端末
  FROM  売上実績テーブル
 WHERE  検収管理NO = @KNO
 ORDER BY 実績年月, 検収管理行NO

検収管理NO	検収管理行NO	実績年月	入力区分	契約先	品番	金額	作成日	作成端末
1196362	3	202607		NULL	6143190K00	0	2026-08-05 10:16:23.150	営業技術2023

PRINT '========== ② 売上明細テーブル側の状況 =========='
SELECT  検収管理NO, 検収管理行NO, 実績年月, 実績検収管理NO, 実績検収管理行NO,
        入力区分, 契約先, 品番, 納入番号, 金額, 作成日, 作成端末
  FROM  売上明細テーブル
 WHERE  検収管理NO = @KNO
 ORDER BY 実績年月, 検収管理行NO

検収管理NO	検収管理行NO	実績年月	実績検収管理NO	実績検収管理行NO	入力区分	契約先	品番	納入番号	金額	作成日	作成端末

PRINT '========== ③【重要】検収テーブルに同番が実在するか（採番衝突の直接証拠）=========='
--  ここに行が返れば、型費が採番した番号が実在の検収伝票と衝突している
SELECT  検収管理NO, 検収管理行NO, 品番, 納入先, 受入, 納入番号,
        検収日, 検収数, 実績年月, 実績処理日, 実績結果, 作成日, 作成端末
  FROM  検収テーブル
 WHERE  検収管理NO = @KNO
 ORDER BY 検収管理行NO

検収管理NO	検収管理行NO	品番	納入先	受入	納入番号	検収日	検収数	実績年月	実績処理日	実績結果	作成日	作成端末

PRINT '========== ④【重要】名称マスタ 検収管理NO の採番状況（原因A〜Dの切分け）=========='
--  数字1 = 端末番号 / 数字2 = 現在連番 / 数字3 = 連番最大値
--  ・数字1 >= 100 が居る            → 原因A（桁割り破綻）
--  ・数字2 が実データ最大連番より小  → 原因C（巻き戻り）
--  ・数字3 が 9999999 でない         → 原因D（一周）
SELECT  値 AS ホスト名, 数字1 AS 端末番号, 数字2 AS 現在連番, 数字3 AS 連番最大値,
        数字2 * 100 + 数字1 AS 次回採番値の目安,
        作成日, 更新日
  FROM  名称マスタ
 WHERE  区分名称 = '検収管理NO'
   AND  区分タイプ = ''
 ORDER BY 数字1

ホスト名	端末番号	現在連番	連番最大値	次回採番値の目安	作成日	更新日

PRINT '========== ④-2 実データ上の最大連番と採番カウンタの突合（原因C）=========='
SELECT  端末番号 = 検収管理NO % 100,
        実データ最大連番 = MAX(検収管理NO / 100),
        件数 = COUNT(*)
  FROM  検収テーブル
 GROUP BY 検収管理NO % 100
 ORDER BY 1

端末番号	実データ最大連番	件数

PRINT '========== ⑤ 端末番号の重複（原因B）=========='
SELECT  数字1 AS 端末番号, COUNT(*) AS ホスト数,
        ホスト一覧 = STUFF((SELECT ', ' + RTRIM(M2.値)
                              FROM 名称マスタ M2
                             WHERE M2.区分名称 = '検収管理NO'
                               AND M2.区分タイプ = ''
                               AND M2.数字1 = M1.数字1
                             FOR XML PATH('')), 1, 2, '')
  FROM  名称マスタ M1
 WHERE  区分名称 = '検収管理NO'
   AND  区分タイプ = ''
 GROUP BY 数字1
HAVING  COUNT(*) > 1
 ORDER BY 数字1

端末番号	ホスト数	ホスト一覧

PRINT '========== ⑥ クライアント管理の端末番号一覧（原因A）=========='
SELECT  登録ホスト数 = COUNT(*),
        端末番号MIN  = MIN(数字1),
        端末番号MAX  = MAX(数字1),
        端末番号100以上 = SUM(CASE WHEN 数字1 >= 100 THEN 1 ELSE 0 END)
  FROM  名称マスタ
 WHERE  区分名称 = 'クライアント管理'
   AND  区分タイプ = ''

SELECT  値 AS ホスト名, 数字1 AS 端末番号, 作成日
  FROM  名称マスタ
 WHERE  区分名称 = 'クライアント管理'
   AND  区分タイプ = ''
   AND  数字1 >= 100
 ORDER BY 数字1

登録ホスト数	端末番号MIN	端末番号MAX	端末番号100以上
72	1.0000	72.0000	0

PRINT '========== ⑦ 202607 売上実績テーブルの状況（入力区分別）=========='
SELECT  実績年月, 入力区分,
        区分名 = CASE 入力区分 WHEN ''  THEN '検収（売上実績作成）'
                               WHEN '2' THEN '型費（売上実績型費）'
                               ELSE '手入力/その他' END,
        件数 = COUNT(*),
        契約先数 = COUNT(DISTINCT 契約先),
        金額計 = SUM(CONVERT(BIGINT, ISNULL(金額,0)))
  FROM  売上実績テーブル
 WHERE  実績年月 = @YM
   AND  (@TORCD = '' OR 契約先 = @TORCD)
 GROUP BY 実績年月, 入力区分
 ORDER BY 入力区分

ホスト名	端末番号	作成日

PRINT '========== ⑧【重要】衝突予備軍の全件洗い出し（復旧規模の見積り）=========='
--  型費由来行（入力区分='2'）の検収管理NO が、実在の検収伝票とぶつかっているもの
SELECT  U.実績年月, U.検収管理NO, U.検収管理行NO, U.入力区分,
        型費側契約先 = U.契約先, 型費側品番 = U.品番, 型費側金額 = U.金額,
        型費側作成日 = U.作成日, 型費側作成端末 = U.作成端末,
        検収側品番   = K.品番,   検収側納入先 = K.納入先,
        検収側検収日 = K.検収日, 検収側実績年月 = K.実績年月
  FROM  売上実績テーブル U
  JOIN  検収テーブル     K
    ON  K.検収管理NO   = U.検収管理NO
   AND  K.検収管理行NO = U.検収管理行NO
 WHERE  U.入力区分 = '2'
 ORDER BY U.実績年月 DESC, U.検収管理NO

実績年月	入力区分	区分名	件数	契約先数	金額計
202607		検収（売上実績作成）	8688	15	176577356
202607	1	手入力/その他	19	7	10092031

PRINT '========== ⑧-2 検収管理NO の重複数（売上実績テーブル内・年月違い含む）=========='
SELECT  検収管理NO, 検収管理行NO,
        年月数 = COUNT(DISTINCT 実績年月),
        区分数 = COUNT(DISTINCT 入力区分),
        年月一覧 = STUFF((SELECT ', ' + U2.実績年月 + '(' + ISNULL(U2.入力区分,'-') + ')'
                            FROM 売上実績テーブル U2
                           WHERE U2.検収管理NO   = U1.検収管理NO
                             AND U2.検収管理行NO = U1.検収管理行NO
                           ORDER BY U2.実績年月
                           FOR XML PATH('')), 1, 2, '')
  FROM  売上実績テーブル U1
 GROUP BY 検収管理NO, 検収管理行NO
HAVING  COUNT(DISTINCT 入力区分) > 1
 ORDER BY 検収管理NO

実績年月	検収管理NO	検収管理行NO	入力区分	型費側契約先	型費側品番	型費側金額	型費側作成日	型費側作成端末	検収側品番	検収側納入先	検収側検収日	検収側実績年月

PRINT '========== ⑨ 対象契約先の型費テーブル状況 =========='
SELECT  取引先, 品番, 対象開始年月, 連番, 金額,
        適用開始年月, 適用終了年月, 回数, 投資金額,
        実績年月, 実績処理日, 更新日, 更新端末
  FROM  型費テーブル
 WHERE  (@TORCD = '' OR 取引先 = @TORCD)
   AND  対象開始年月 <= @YM
   AND  (ISNULL(実績年月,'') = '' OR ISNULL(実績年月,'') = @YM)
 ORDER BY 取引先, 品番, 対象開始年月, 連番

実績年月	検収管理NO	検収管理行NO	入力区分	型費側契約先	型費側品番	型費側金額	型費側作成日	型費側作成端末	検収側品番	検収側納入先	検収側検収日	検収側実績年月

PRINT '========== ⑩ 売上元の設定確認（検収ベース／出荷ベース）=========='
--  oyian の1桁目が '1' なら「出荷」ベース、それ以外は「検収」ベース
SELECT  bk, rno, oyian, oyian2, etadpu,
        売上元 = CASE WHEN SUBSTRING(ISNULL(oyian,''),1,1) = '1'
                      THEN '出荷ベース' ELSE '検収ベース' END
  FROM  Irnaksic
 WHERE  bk = 'Option'
   AND  rno = 50

実績年月	検収管理NO	検収管理行NO	入力区分	型費側契約先	型費側品番	型費側金額	型費側作成日	型費側作成端末	検収側品番	検収側納入先	検収側検収日	検収側実績年月

PRINT '========== ⑪ 対象契約先の取引先マスタ設定 =========='
SELECT  取引先CD, 取引先区分, 正式名称, 略称, 締日, 計算方法, 計算単位, 計算位1, 計算位2
  FROM  取引先マスタ
 WHERE  取引先区分 = 0
   AND  (@TORCD = '' OR 取引先CD = @TORCD)
 ORDER BY 取引先CD
